if (nrow(su_kaynak_long) &gt; 0) {
  su_kaynak_pay &lt;- su_kaynak_long |&gt;
    group_by(yil) |&gt;
    mutate(
      pay = su_bin_m3 / sum(su_bin_m3, na.rm = TRUE)
    ) |&gt;
    ungroup()

  ggplot(su_kaynak_pay, aes(x = factor(yil), y = pay, fill = kaynak_turu)) +
    geom_col(position = "fill") +
    scale_y_continuous(labels = percent) +
    labs(
      title = "Su Kaynaklarının Yüzdesel Payı",
      x = "Yıl",
      y = "Pay",
      fill = "Kaynak Türü"
    ) +
    theme_minimal()
}









Kaynak kompozisyonu Ankara’nın su arzında barajların stratejik önemini göstermektedir. Baraj kaynaklı suyun baskın hale gelmesi, yağış rejimi ve baraj doluluklarının su yönetimi açısından daha kritik hale gelmesine neden olmaktadır.

3.1 Yardımcı Fonksiyonlar


Kodu Göster / Gizle
bul_dosya &lt;- function(adaylar) {
  olasi_yollar &lt;- unlist(
    map(adaylar, ~ c(file.path("data", .x), .x))
  )
  bulunan &lt;- olasi_yollar[file.exists(olasi_yollar)]

  if (length(bulunan) == 0) {
    stop(
      paste0(
        "Dosya bulunamadı. Aranan adaylar: ",
        paste(adaylar, collapse = ", "),
        "\nDosyayı proje klasörüne veya data/ klasörüne koyunuz."
      )
    )
  }

  bulunan[1]
}

bul_dosya_opsiyonel &lt;- function(adaylar) {
  olasi_yollar &lt;- unlist(
    map(adaylar, ~ c(file.path("data", .x), .x))
  )
  bulunan &lt;- olasi_yollar[file.exists(olasi_yollar)]

  if (length(bulunan) == 0) {
    return(NA_character_)
  }

  bulunan[1]
}

hacim_sayi &lt;- function(x) {
  if (is.numeric(x)) {
    return(as.numeric(x))
  }

  x &lt;- as.character(x)
  x &lt;- str_squish(x)
  x &lt;- str_replace_all(x, "\\s", "")
  x &lt;- str_replace_all(x, "\\.", "")
  x &lt;- str_replace_all(x, ",", ".")
  as.numeric(x)
}

yuzde_sayi &lt;- function(x) {
  if (is.numeric(x)) {
    return(as.numeric(x))
  }

  x &lt;- as.character(x)
  x &lt;- str_squish(x)
  x &lt;- str_replace_all(x, "%", "")

  if_else(
    str_detect(x, ","),
    as.numeric(str_replace(str_replace_all(x, "\\.", ""), ",", ".")),
    as.numeric(x)
  )
}

